delete from creator_patterns where kind='script' and content_type='reel';
insert into creator_patterns (kind, content_type, style, style_desc, formula, examples, guide, weight, active) values
('script','reel','프랭크-맛집30초',
 '맛집 인스타 릴스 30초 내레이션 — 위치·가게명 오프닝→주문 나열→메뉴별 맛 묘사→킥 공개→저장 유도 클로징',
 '[0-4s 오프닝] 지역+랜드마크+가게명 ("논현역 5번 출구 첫 골목 성천막국수입니다") + 한 줄 아이덴티티("3대째 60년 이어 온 막국수 노포예요") → [4-8s 주문] 시킨 메뉴 나열("물막국수 비빔막국수 제육 반접시 주문했어요") → [8-22s 본론] 메뉴별 2-3개 맛 묘사: 조리방식/식감/맛 디테일+감각 비유("자다가도 생각나는 지독한 중독성") → [22-26s 킥] "이 집 진짜 킥은 ___" 시그니처 포인트(메뉴에 없는 것/모르면 손해 조합) → [26-30s 클로징] 가격 정보 or 행동 유도("무조건 저장했다 꼭 드세요"/"오픈런만이 답입니다"). 총 55-65어절 구절, 한 구절 2-4어절. 존댓말 종결 리듬 교차: ~입니다/~예요/~고요/~습니다.',
 '예1(오뎅바): "신사동 가로수길 골목 안 타이키입니다 / 진짜 일본식 오뎅바예요 / 자리가 좁아서 예약하고 가는 게 좋습니다 / 무조림 달걀 곤약 소세지 오징어 스지까지 먹어봤어요 / 역시 제일 맛있었던 건 무조림 / 오래 끓여서 부드럽게 으깨지는데 다시가 속까지 짭조름하게 배어있었어요 / 이 집 진짜 킥은 메뉴에도 없는 크로와상 오뎅입니다 / 버터 올리고 토치로 구워주는데 진짜 크로와상 같은 질감이라 신기했어요 / 삿포로 생맥주에 니혼슈까지 곁들이면 딱이고요 / 단골이 안될 수가 없는 곳입니다" · 예2(중식): "신림동 중화요리 팔공입니다 / 유린기는 한국 1등이라는 얘기가 나오는 곳이에요 / 반드시 저장하세요 / 유린기 간짜장 짬뽕 볶음밥을 주문했습니다 / 바삭한 튀김에 새콤달콤한 소스에 청양고추 고명이 입안에서 팡팡 터지는데 그냥 입안이 축제입니다 / 재료 소진 시 바로 마감이라 오픈런만이 답입니다 빨리 뛰어가세요"',
 '읽는 속도 기준 30초=약 55-65어절(구절 단위로 끊어 읽기 좋게). 클립 개수만큼 문단을 나눠서 각 문단이 한 클립(장면)에 얹히게. 과장 대신 구체 디테일(가격·등급·조리법·조합). 후킹 단어: 노포/킥/한정/1등/오픈런/저장. 금지: 사실 날조, 실제 안 준 정보(가격 등) 지어내기.',
 9, true),
('script','reel','프랭크-오프닝포맷',
 '릴스 첫 3초 오프닝 변형 3종 — 지역훅/최상급훅/경고훅',
 'A.지역훅: "○○역 N번 출구 첫 골목 [가게명]입니다" B.최상급훅: "[메뉴] 한국 1등이라는 얘기가 나오는 곳이에요" C.경고훅: "3인 이상은 절대 입장이 안됩니다" 같은 반전 규칙 먼저. 오프닝 직후 반드시 아이덴티티 한 줄(연차/노포/컨셉).',
 '"대치동 철수네 포장마차입니다 / 할아버지 혼자 운영하시는 노포 포차인데 / 3인 이상은 절대 입장이 안됩니다" · "종로 낙원 악기상가 지하시장 일미식당입니다 / 지하 던전 같은 분위기로 7~80년대 모습이 그대로 남아 있어요"',
 '훅은 상대가 준 정보에서만 뽑는다. 위치가 특이하면 지역훅, 시그니처가 강하면 최상급훅, 규칙·제약이 있으면 경고훅.',
 7, true);
